const c=r=>new Promise((s,o)=>{if(!r||!["image/png","image/jpeg","image/webp"].includes(r.type)){o(new Error("Escolha uma imagem PNG, JPG ou WebP."));return}if(r.size>5242880){o(new Error("A imagem deve ter no máximo 5 MB."));return}const e=new Image,n=URL.createObjectURL(r);e.onload=()=>{URL.revokeObjectURL(n);const a=document.createElement("canvas");a.width=256,a.height=256;const i=a.getContext("2d");if(!i){o(new Error("Não foi possível processar a imagem."));return}const t=Math.min(e.width,e.height);i.drawImage(e,(e.width-t)/2,(e.height-t)/2,t,t,0,0,256,256);const m=a.toDataURL("image/webp",.8);if(m.length>35e4){o(new Error("A imagem compactada ficou muito grande. Escolha outra foto."));return}s(m)},e.onerror=()=>{URL.revokeObjectURL(n),o(new Error("Não foi possível abrir essa imagem."))},e.src=n});export{c as r};
